SELECT a.id,a.name,a.city,a.country,a.address,a.open_time,a.adult_ticket_price,a.child_ticket_price, a.longitude,a.latitude,a.phone,a.description,a.stars,a.rating,a.tags, (SELECT ai.image FROM attraction_image ai WHERE ai.attraction_id = a.id ORDER BY ai.sort_order LIMIT 1) AS mainImage FROM attraction a
(a.name LIKE CONCAT('%', #{keyword}, '%') OR a.city LIKE CONCAT('%', #{keyword}, '%') OR a.country LIKE CONCAT('%', #{keyword}, '%') OR a.address LIKE CONCAT('%', #{keyword}, '%') OR a.description LIKE CONCAT('%', #{keyword}, '%'))
AND a.city = #{city}
AND (
FIND_IN_SET(#{tag}, a.tags) > 0
)
AND a.stars = #{stars}
AND a.rating IS NULL AND a.id < #{lastId}
AND (a.rating < #{lastValue} OR a.rating IS NULL OR (a.rating = #{lastValue} AND a.id < #{lastId}))
ORDER BY a.rating DESC, a.id DESC LIMIT #{size}

SELECT id,name,city,address,open_time,adult_ticket_price AS price,stars,rating,tags,ai.image AS image
FROM attraction LEFT JOIN attraction_image AS ai ON  ai.attraction_id = id AND ai.sort_order = 1

    AND city = #{city}

SELECT id,name,city,address,description,open_time,adult_ticket_price AS price,rating,tags,ai.image AS image
FROM attraction LEFT JOIN attraction_image AS ai ON  ai.attraction_id = id AND ai.sort_order = 1
WHERE id = #{id}
